#include <Arduino.h>
#include <Wire.h>
#include "bmp280-driver.h"

static uint16_t dig_T1;
static int16_t dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

static uint8_t read8(uint8_t address, uint8_t reg) {
  Wire.beginTransmission(address);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(address, (uint8_t)1);
  return Wire.read();
}

static uint16_t read16le(uint8_t address, uint8_t reg) {
  uint16_t lo = read8(address, reg);
  uint16_t hi = read8(address, reg + 1);
  return (hi << 8) | lo;
}

static int32_t read20(uint8_t address, uint8_t reg) {
  Wire.beginTransmission(address);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(address, (uint8_t)3);
  int32_t value = Wire.read();
  value = (value << 8) | Wire.read();
  value = (value << 8) | Wire.read();
  return value >> 4;
}

void bmp280_init(uint8_t address) {
  Wire.begin();
  dig_T1 = read16le(address, 0x88);
  dig_T2 = (int16_t)read16le(address, 0x8A);
  dig_T3 = (int16_t)read16le(address, 0x8C);
  dig_P1 = read16le(address, 0x8E);
  dig_P2 = (int16_t)read16le(address, 0x90);
  dig_P3 = (int16_t)read16le(address, 0x92);
  dig_P4 = (int16_t)read16le(address, 0x94);
  dig_P5 = (int16_t)read16le(address, 0x96);
  dig_P6 = (int16_t)read16le(address, 0x98);
  dig_P7 = (int16_t)read16le(address, 0x9A);
  dig_P8 = (int16_t)read16le(address, 0x9C);
  dig_P9 = (int16_t)read16le(address, 0x9E);
  Wire.beginTransmission(address);
  Wire.write(0xF4);
  Wire.write(0x27);  // temperature x1, pressure x1, normal mode
  Wire.endTransmission();
}

static int32_t compensate_t_fine(uint8_t address) {
  int32_t adc = read20(address, 0xFA);
  int32_t var1 = ((((adc >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
  int32_t var2 = (((((adc >> 4) - ((int32_t)dig_T1)) * ((adc >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
  return var1 + var2;
}

float bmp280_read_temperature(uint8_t address) {
  int32_t t_fine = compensate_t_fine(address);
  return ((t_fine * 5 + 128) >> 8) / 100.0f;
}

float bmp280_read_pressure(uint8_t address) {
  int32_t t_fine = compensate_t_fine(address);
  int32_t adc = read20(address, 0xF7);
  int64_t var1 = (int64_t)t_fine - 128000;
  int64_t var2 = var1 * var1 * (int64_t)dig_P6;
  var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
  var2 = var2 + (((int64_t)dig_P4) << 35);
  var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
  var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
  if (var1 == 0) return 0;
  int64_t p = 1048576 - adc;
  p = (((p << 31) - var2) * 3125) / var1;
  var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
  var2 = (((int64_t)dig_P8) * p) >> 19;
  p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
  return (float)p / 256.0f;  // pascals
}
